import json, time, urllib.request, urllib.error
from datetime import datetime, timezone
from decimal import Decimal
B="http://localhost:8080"
tok=None
log={}
def raw(path, method="GET", auth=True):
    h={}
    if auth and tok: h["Authorization"]="Bearer "+tok
    r=urllib.request.Request(B+path, method=method, headers=h, data=b"" if method=="POST" else None)
    try:
        with urllib.request.urlopen(r, timeout=30) as f: return f.status, dict(f.headers), f.read()
    except urllib.error.HTTPError as e: return e.code, dict(e.headers), e.read()
    except Exception as e: return 0, {}, str(e).encode()
def newtok():
    global tok
    while True:
        s,h,b=raw("/token","POST",False)
        if s==200: tok=json.loads(b)["token"]; return
        time.sleep(1)
def get(path):
    for _ in range(200):
        s,h,b=raw(path)
        if s==200:
            try: return json.loads(b)
            except Exception: log["badjson"]=log.get("badjson",0)+1; continue
        if s==404: return None
        log[s]=log.get(s,0)+1
        if s==401 or s==403: newtok(); continue
        if s==429:
            ra=h.get("Retry-After"); 
            try: w=float(ra)
            except: w=1
            log.setdefault("ra",set()).add(str(ra)); time.sleep(w); continue
        log.setdefault("other",[]).append((s,b[:100])); time.sleep(1)
    raise SystemExit("gave up "+path)
newtok()
orders=[]; p=1
while True:
    d=get(f"/orders?page={p}")
    orders+=d["items"]
    if not d["next"]: break
    p+=1
    tp=d["total_pages"]
print("pages",p,"total_pages",tp,"raw items",len(orders))
seen={}; dups=0
for o in orders:
    if o["id"] in seen:
        dups+=1
        if seen[o["id"]]!=o: print("DUP DIFFERS",o,seen[o["id"]])
    else: seen[o["id"]]=o
print("distinct",len(seen),"dups",dups)
from collections import Counter
print(Counter(o["status"] for o in seen.values()))
lo=datetime(2025,3,1,tzinfo=timezone.utc); hi=datetime(2025,6,1,tzinfo=timezone.utc)
def parse(s):
    d=datetime.fromisoformat(s.replace("Z","+00:00"))
    if d.tzinfo is None: print("NAIVE",s); d=d.replace(tzinfo=timezone.utc)
    return d.astimezone(timezone.utc)
q=[o for o in seen.values() if o["status"]=="shipped" and lo<=parse(o["placed_at"])<hi]
cust={}
for o in q:
    c=o["customer_id"]
    if c not in cust: cust[c]=get(f"/customers/{c}")
missing=[c for c,v in cust.items() if v is None]
print("missing customers",missing)
reg={"north":0,"south":0,"east":0,"west":0}; n=0
for o in q:
    c=cust[o["customer_id"]]
    if c is None: continue
    a=o["amount_cents"]; assert isinstance(a,int)
    dp=c["discount_pct"]; assert isinstance(dp,int)
    v=(a*(100-dp)*2+100)//200  # half up of a*(100-dp)/100
    reg[c["region"]]+=v; n+=1
res={"total_cents":sum(reg.values()),"order_count":n,"duplicates_skipped":dups,"by_region":reg}
print(res); print({k:v for k,v in log.items()})
json.dump(res,open("/workspace/result.json","w"),indent=2)
